# Build all questions
for topic, qas in llm_topics.items():
    for q, a in qas:
        new_questions.append({"id": new_id, "question": q, "category": "LLM大模型", "difficulty": 3, "answer": a})
        new_id += 1

for topic, qas in agent_bulk_topics.items():
    for q, a in qas:
        new_questions.append({"id": new_id, "question": q, "category": "AI Agent", "difficulty": 4, "answer": a})
        new_id += 1

data.extend(new_questions)

# Re-assign IDs
for i, q in enumerate(data):
    q['id'] = i + 1

with open('public/data.json', 'w', encoding='utf-8') as f:
    json.dump(data, f, ensure_ascii=False)

print(f"Added {len(new_questions)} new questions")
llm_count = sum(1 for q in data if q['category'] == 'LLM大模型')
agent_count = sum(1 for q in data if q['category'] == 'AI Agent')
total = len(data)
print(f"LLM大模型: {llm_count} ({llm_count*100/total:.1f}%)")
print(f"AI Agent: {agent_count} ({agent_count*100/total:.1f}%)")
print(f"Total: {total}")
